import json

# Burden of proof allocation stated in the text (fault presumption liability):
stated = {
    "victim_must_prove": {"damage caused by constructor's behavior"},
    "constructor_must_prove": {"constructor not at fault"},
    "victim_must_prove_constructor_fault": False,  # fault is presumed
}

# Each option expressed as the claims it needs from the text.
options = {
    "A": {"victim_proves": "victim has been harmed"},
    "B": {"victim_proves": "damage caused by constructor's behavior"},
    "C": {"victim_proves": "victim not at fault"},
    "D": {"victim_proves": "victim not at fault is NOT required",
          "constructor_proves": "constructor not at fault"},
}

def supported(key):
    o = options[key]
    ok = True
    if "victim_proves" in o:
        claim = o["victim_proves"]
        if key in ("A", "B", "C"):
            ok = ok and claim in stated["victim_must_prove"]
    if key == "D":
        # The text says nothing about the victim's own fault, so the
        # second clause is not derivable from it.
        ok = ok and False
    return ok

results = {k: supported(k) for k in options}
inferable = [k for k, v in results.items() if v]

if len(inferable) == 1:
    out = {"final_answer": inferable[0],
           "evidence": {"supported": results,
                        "victim_burden": sorted(stated["victim_must_prove"]),
                        "constructor_burden": sorted(stated["constructor_must_prove"])}}
else:
    out = {"final_answer": "UNSUPPORTED", "evidence": results}

print(json.dumps(out))
